insert into public.curriculum_items
  (class_name, subject, subject_key, strand, sub_strand, content_standard_code, content_standard, indicator_code, indicator, exemplar, sort_order)
values
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B5.1.1.1', 'Identify parts of a computer and technology tools', 'B5.1.1.1.1', 'Recognise and use output devices', 'Guide learners to recall what they learnt in the previous classes and ask them to m e n t i o n c o m p u t e r d e v i c e s t h a t p r o d u c e o u t p u t Softcopy- computer monitor/projector, audio electrical signals etc. Hardcopy- printed images, pictures documents, NB: This is to help the learner with hardware knowledge.', 10),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B5.1.1.1', 'Identify parts of a computer and technology tools', 'B5.1.1.1.2', 'Describe the types of output device and identify their uses', 'Guide learners to identify types of output devices and their uses. Assist them to list them on the board as well as their uses.', 20),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B5.1.1.1', 'Identify parts of a computer and technology tools', 'B5.1.1.1.3', 'Distinguish the difference and similarities between analogue and digital devices', 'e.g. telephone, mobile phone, radio, tablets, satellite etc. Guide the learners to identify the similarities and differences between analogue and digital devices. Present examples of analogue and digital devices to learners. Aid them to mention other examples of analogue devices and digital devices as well as noticing the differences.', 30),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B5.1.1.1', 'Identify parts of a computer and technology tools', 'B5.1.1.1.4', 'Identify the left, right mouse button, holding of mouse, performing single, double and triple clicking and dragging object', 'Guide learners to use the mouse to perform performing single, double and triple clicking and dragging object into a folder or bring picture(s) describing the processes; single, double and triple clicking and dragging objects into a folder and ask leaners to point out a mentioned process.', 40),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B5.1.1.1', 'Identify parts of a computer and technology tools', 'B5.1.1.1.5', 'Identify home row keys, top row, bottom row keys, numerical pad and type (short sentences)', 'Guide learners to type using top row keys (Q, W, E, R, and T keys for the left-hand and Y, U, I, O, and P keys for the right-hand), bottom row keys (Z, X, C, V, and B keys for the left-hand and N, M, comma, period, and forward slash keys for the right-hand), numerical pad (1, 2, 3, …9. etc.) and type an essay (50 words) using Word Processor or typing tutorial', 50),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B5.1.1.1', 'Identify parts of a computer and technology tools', 'B5.1.1.1.6', 'Introduction to Windows Interface', 'Guide learners to list the features (i.e. Start Menu Returns, Cortana on Desktop, Xbox App, Project Spartan Browser, etc.) and compatibility issues of Windows; 10. Do this by using leading questions, or any other method.', 60),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Generation of Computers and Parts of a Computer and Other Gadgets', 'B5.1.1.1', 'Identify parts of a computer and technology tools', 'B5.1.1.1.7', 'Summarise the generation of computers', 'Guide learners to recall what has been learnt in previous classes and ask leading questions, use scenarios to help learners identify the difference between the types of computers, their advantages and disadvantages. NB: Learners can practice with the keyboard only in the absence of the applications. Learners should be guided to play computer games to re-enforce keyboard and mouse skills.', 70),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B5.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B5.1.2.1.1', 'Personalise the Desktop Background and edit its images (', 'e.g. image, icons and Taskbar of the background). Guide learners to create their own background picture using any application (e.g. paints). Guide them to use it as background picture.', 80),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B5.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B5.1.2.1.2', 'Recognise how to customise the Desktop Background using Change Background, Start menu and Pin to taskbar or start menu', 'Guide learners to identify and use task bar, start menu, etc.', 90),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B5.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B5.1.2.1.3', 'Describe how to Personalise the Desktop Background using advance tools and settings', 'Guide learners to customize the Start Menu and the Notification Area.', 100),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B5.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B5.1.2.1.4', 'Creating a short cut, adding or removing common icons on the desktop', 'Guide learners to create shortcuts of icons on the computers’ desktop.', 110),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B5.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B5.1.2.1.5', 'Moving, copying and pasting a file or icon into and from a folder on the desktop Guide learners to copy and paste a file or icon into and from a folder on the desktop', null, 120),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Introduction to Ms-windows Interface (desktop Background and Locations of the Computer)', 'B5.1.2.1', 'Demonstrate the use of the Desktop Background as well as working with folders', 'B5.1.2.1.6', 'Demonstrate understanding of the File Explorer window and locations of the computer through the file explorer', 'Guide learners to use the file explorer to locate files. NB: This is to help the learner with the fundamental skills of creativity in computing and Computer Science.', 130),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.1', 'Use Strategies for identifying data from results of an experiment', 'Guide learners to identify the types of data (qualitative and quantitative) by asking leading questions. Task them to convert data from one format to another without losing its value.', 140),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.2', 'Identify primary sources of information', 'e.g. photographs, audio, video recordings, letters etc. Guide learners to mention or talk about primary sources of information. Task learners to record data from the primary source and bring them to class for discussion. List items recorded and ask learners to group according to their similarities.', 150),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.3', 'Identify secondary sources of information', 'e.g. radio, fax, telephones calls, SMS etc. Guide learners to mention or talk about where one can receive or send information by asking leading questions. Task learners to record data from the news on the radio and bring to class for discussion. List items recorded and ask learners to group according to their similarities.', 160),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.4', 'Demonstrate sending and sharing information', 'e.g. arranging data, sorting and calculations etc. Task learners to sort data in alphabetical order (increasing and decreasing order) and perform basic calculations such as multiplying, dividing and adding vales of sample data. Learners can also be guided to generate age data from their dates of birth. NB: recall content in B4 and add to it.', 170),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.5', 'Demonstrate basic calculations on sample data', 'e.g. arranging and summing and averaging data. Guide learners to add and find the average data collected and present their findings to the class', 180),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.6', 'Recognise data types (integer, double, float)', 'Divide learners into two groups and ask one group to mention a number and the other group to identify the type of data mentioned', 190),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.7', 'Demonstrate sending and sharing information', 'Guide learners to send messages to each other via SMS, email. etc. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and computer science.', 200),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.8', 'Select the samples and collect data (', 'e.g. listening to radio, newspaper, talking to people etc.) Put learners into groups, task them to interview teachers using simple questionnaire, and record the data in books.', 210),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.9', 'Make simple tables and diagrams from the collected data', 'Bring tools or pictures of the tools in a box or container and ask learners to select tools for collecting data out of the box or container. Alternatively, ask learners to bring tools for collecting data for a class discussion.', 220),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Data, Sources and Usage', 'B5.1.3.1', 'Illustrate the use of Data and identify their sources', 'B5.1.3.1.10', 'Analyse tables, maps, diagrams, photographs and charts, and generalize the results and make suggestions (', 'e.g. Finding sum or grand total). Task learners to calculate the average, mean, sum and difference between data collected in an earlier class. NB: This is to help the learner with fundamental principle of problem solving skills and creativity in computing and computer science.', 230),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community (communication)', 'B5.1.4.1', 'Demonstrate the use of Technology in the community', 'B5.1.4.1.1', 'List the effects of technology on the community. Guide learners to investigate the types and types importance of compression of document Positive effects', '– health care, education, manufacturing, agriculture etc. Negative effects – resource depletion ,pollution, privacy and security etc.,', 240),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community (communication)', 'B5.1.4.1', 'Demonstrate the use of Technology in the community', 'B5.1.4.1.2', 'Explain the fundamentals of digital system components (hardware, software and networks)', 'Guide learners to brainstorm the basics of digital system components such as hardware, software and networks).', 250),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community (communication)', 'B5.1.4.1', 'Demonstrate the use of Technology in the community', 'B5.1.4.1.3', 'Discuss how technology is used to save lives in community and how they are used Guide learners to explore how technology is used to save lives in communities', 'Group them into groups of a maximum of five and let them present their findings to the class.', 260),
('Basic 5', 'Computing', 'computing', 'Introduction to Computing', 'Technology in the Community (communication)', 'B5.1.4.1', 'Demonstrate the use of Technology in the community', 'B5.1.4.1.4', 'Discuss the effects of technology on the community. Guide learners to brainstorm the effects of technology on the community. Show learners videos or pictures of effects of technology on the community. Let them discuss in groups, the effects of technology on their own community. Positive effects', '– health care, education, manufacturing, agriculture etc. Negative effects – resource depletion, pollution, privacy and security etc. NB: This is to help the learners to have fundamental knowledge of hardware such as robots and sensors).', 270),
('Basic 5', 'Computing', 'computing', 'Presentation', 'Introduction to Ms-powerpoint (tabs and Ribbons of Ms-powerpoint)', 'B5.2.1.1', 'Demonstrate how to use Microsoft PowerPoint', 'B5.2.1.1.1', 'Show the use of Insert, design, animation and transition in the ribbons section', '(New, Open, Save, Save As, Print and Close) and the Insert and design ribbon. Ask learners to use “File menu”, “Insert” and “Design Ribbons” to create a new MS-PowerPoint slide and use shapes in the “Insert ribbon” to draw the Ghana flag”.', 280),
('Basic 5', 'Computing', 'computing', 'Presentation', 'Introduction to Ms-powerpoint (tabs and Ribbons of Ms-powerpoint)', 'B5.2.1.1', 'Demonstrate how to use Microsoft PowerPoint', 'B5.2.1.1.2', 'Show a 5-slide presentation using of Insert, design, animation and transition of the ribbons studied', 'Ask learners to use “File menu”, “Insert” and “Design Ribbons” to design a colourful 5-paged MS-PowerPoint on the topic “Myself” NB. This is to help learners with software knowledge). to understand the concept well in office applications (Microsoft PowerPoint)', 290),
('Basic 5', 'Computing', 'computing', 'Word Processing', 'Introduction to Word Processing (tabs and Ribbons of Word Processing)', 'B5.3.1.1', 'Illustrate the use of word processing', 'B5.3.1.1.1', 'Demonstrate the use of Insert, Design, and Layout (New, Open, Save, Save As, Print and Close) and Insert, Design, and Layout ribbons', '(i.e. clipboard, slides, fonts and paragraph). Guide learners to use File menu, Insert, Design and Layout Ribbon.', 300),
('Basic 5', 'Computing', 'computing', 'Word Processing', 'Introduction to Word Processing (tabs and Ribbons of Word Processing)', 'B5.3.1.1', 'Illustrate the use of word processing', 'B5.3.1.1.2', 'Illustrate the use Insert, Design and Layout', 'Guide the learners to create and format a document. NB. This is to help learners with software knowledge such as office applications (word processing).', 310),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.2', 'Demonstrate how to use Electronic Spreadsheet', 'B5.5.1.2.1', 'Identify Electronic Spreadsheets and their uses', 'Play video on Electronic Spreadsheets and their uses in society. Assist learners to list examples of Electronic Spreadsheets (MS Excel, Numbers, Google sheets, Lotus 1-2-3 etc.). Guide learners to explore the uses of electronic spreadsheets.', 320),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.2', 'Demonstrate how to use Electronic Spreadsheet', 'B5.5.1.2.2', 'Learners discuss the importance of Electronic Spreadsheets', 'Guide learners to discuss the importance of Electronic Spreadsheets and what they are used for.', 330),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.2', 'Demonstrate how to use Electronic Spreadsheet', 'B5.5.1.2.3', 'Learners get familiar with the interface of MS-Excel Guide Learners to demonstrate how to access MS-Excel on any computer or gadget and display text in MS-Excel', 'NB. This is to help the learner with an understanding of application softwares (Electronic Spreadsheet application).', 340),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.3', 'Demonstrate how to use Databases', 'B5.5.1.3.1', 'Describe databases. Guide learners to identify the features of a database and the types of databases that exist', 'Ask learners to select the databases form a list of items written on the board.', 350),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.3', 'Demonstrate how to use Databases', 'B5.5.1.3.2', 'Discuss the importance and uses of database', 'Play a video of the importance and uses of databases and ask learners to mention other uses of database and their importance. Assist learners to realise that Database designers typically organise the data to model aspects of reality in a way that supports processes requiring information.', 360),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.3', 'Demonstrate how to use Databases', 'B5.5.1.3.3', 'Describe the types of database', 'Guide learners to describe the types of database.', 370),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.3', 'Demonstrate how to use Databases', 'B5.5.1.3.4', 'Identify types of databases and data', 'Guide learners to investigate on the types of databases and data. Let learners present their findings to the class.', 380),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.3', 'Demonstrate how to use Databases', 'B5.5.1.3.5', 'Explain fundamental database concepts. Guide learners to explore the fundamental database concepts', 'e.g. tables and data types, data selection and manipulation, security, and backup and restore.', 390),
('Basic 5', 'Computing', 'computing', 'Programming and Databases', 'Introduction to Databases, Algorithm and Programming', 'B5.5.1.3', 'Demonstrate how to use Databases', 'B5.5.1.3.6', 'Discuss programming languages and their use (', 'e.g. scratch, vb.net etc.) Guide learners to investigate in groups on the programming languages and their use (e.g. scratch, vb.net etc.) NB: This is to give a foundation to the learner in computing and Computer Science which is more concerned with uses of and development of programming together with fundamental principles of problem-solving and creativity.', 400),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Network Overview', 'B5.6.1.1', 'Demonstrate how to Network computers', 'B5.6.1.1.1', 'Explain what a network is', 'Guide the learners to discuss how devices communicate. Demonstrate simple connectivity between nodes.', 410),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Network Overview', 'B5.6.1.1', 'Demonstrate how to Network computers', 'B5.6.1.1.2', 'Describe how the internet works', 'Guide learners to distinguish between PAN, LAN, MAN, WAN and Internet.', 420),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Network Overview', 'B5.6.1.1', 'Demonstrate how to Network computers', 'B5.6.1.1.3', 'Explain what the Internet is', 'Guide learners to discuss the inter-connection of the internet computers (learners should be made to realise that the internet is a network of networks). Also, guide learners to come out with examples of Internet Communication.', 430),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.1', 'Explain what a web browser is and its use', 'Guide learners to understand the concept and use of browsers through practical lessons. Show interfaces or images of browsers to learners.', 440),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.2', 'Identify web browsers. Guide learners to list the various types of browsers', 'e.g. Firefox, Internet Explorer, Chrome etc. through practical lessons or the use of pictures', 450),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.3', 'Demonstrate the use of MS-Internet Explorer', 'Guide learners to launch MS-Internet Explorer and use the components (navigation, browse, etc.)', 460),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.4', 'Show how to create and remove a favorites link', 'Guide learners to practice how to create or remove favorite links in practical session(s).', 470),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.5', 'Create favorites folder. Guide learners to practice how to create a favorites folder through practical session(s)', null, 480),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.6', 'Use the links toolbar. Guide learners to practice the use of link toolbar through practical session(s)', 'NB: This is to help the learner with the fundamental skills of creativity in computing and Computer Science.', 490),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.7', 'Explain what a Web Page is', 'Guide learners to explore features of a Web Page (text, graphics, audio, video, animation etc. through practical lessons)', 500),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.8', 'Explain what a home page is', 'Guide learners to identify a home page from other web pages, through practical lessons.', 510),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Web Browsers and Web Pages', 'B5.6.2.1', 'Demonstrate how to use Web Pages', 'B5.6.2.1.9', 'Movement within and between web pages using hyperlinks', 'Guide learners to practice clicking hyperlinks, through practical lessons. NB: This is to help the learner with the fundamental skills of creativity in computing and Computer Science.', 520),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B5.6.3.1', 'Demonstrate how to use Favorite places', 'B5.6.3.1.1', 'Show how to create a favorite link', 'Guide learners to create a favorite link. .', 530),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B5.6.3.1', 'Demonstrate how to use Favorite places', 'B5.6.3.1.2', 'Demonstrate deleting favorite links', 'Guide learners to delete favorite links they have created in the previous lesson.', 540),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B5.6.3.1', 'Demonstrate how to use Favorite places', 'B5.6.3.1.3', 'Create favorite folder. Guide learners to create a favorite folder', null, 550),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Surfing the World Wide Web', 'B5.6.3.1', 'Demonstrate how to use Favorite places', 'B5.6.3.1.4', 'Use the links toolbar. Guide learners to use the links toolbar', 'NB: This is to help the learner with the fundamental skills of surfing and navigating the internet.', 560),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B5.6.4.1', 'Demonstrate how to use Search Engines', 'B5.6.4.1.1', 'Identify common search engines', 'Guide learners to discuss search engines and the different types search engines (Google, DuckDuckGo, Yahoo etc.)', 570),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B5.6.4.1', 'Demonstrate how to use Search Engines', 'B5.6.4.1.2', 'Explore how smart search engines work', 'Guide learners to how smart search engines work (i.e. how professionals or people seek information for their work or interests and what information they draw from it).', 580),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B5.6.4.1', 'Demonstrate how to use Search Engines', 'B5.6.4.1.3', 'Demonstrate how to handle search results', 'Guide learners to explore how to handle search results from a search engine. NB: This is to help the learner with the fundamental skills of surfing and navigating the internet.', 590),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Favourite Places and Search Engine', 'B5.6.4.9', 'Demonstrate the use of Internet of Things (IoT) CONT’D', 'B5.6.4.9.1', 'Demonstrate proficiency in Digital Literacy', null, 600),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B5.6.5.1', 'Demonstrate the Usage of Forms', 'B5.6.5.1.1', 'Identify and describe forms in a web page', 'Guide learners to fill out dropdown boxes, combo box, Text fields etc.', 610),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B5.6.5.1', 'Demonstrate the Usage of Forms', 'B5.6.5.1.2', 'Demonstrate working on or offline', 'Guide learners to register or fill out online forms as well as offline through practical sessions. Learners can be guided to use created PDF or Word forms to practice filling out forms offline.', 620),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Using Online Forms', 'B5.6.5.1', 'Demonstrate the Usage of Forms', 'B5.6.5.1.3', 'Demonstrate downloading of files (', 'e.g. pictures, audio, pdf etc.). Guide learners to download a file through practical session(s).', 630),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B5.6.6.1', 'Show how to Customize a Browser', 'B5.6.6.1.1', 'Demonstrate how to set default search engines', 'Guide learners to set default search engines.', 640),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B5.6.6.1', 'Show how to Customize a Browser', 'B5.6.6.1.2', 'Show how to set homepages', 'Guide learners to set homepages.', 650),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B5.6.6.1', 'Show how to Customize a Browser', 'B5.6.6.1.3', 'Show how to make Browser apps, add-ons, plug-ins, and extensions', 'Guide learners to make Browser apps, add-ons, plug-ins, and extensions.', 660),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B5.6.6.1', 'Show how to Customize a Browser', 'B5.6.6.1.4', 'Illustrate how to customise the browser toolbar', 'Facilitate learners to customise the browser toolbar.', 670),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B5.6.6.1', 'Show how to Customize a Browser', 'B5.6.6.1.5', 'Identify cookies in web browsers', 'Aid learners to recognize cookies in web browsers.', 680),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Customizing Your Browser', 'B5.6.6.1', 'Show how to Customize a Browser', 'B5.6.6.1.6', 'Illustrate how to set disk space or cache usage', 'Guide learners to set disk space or cache usage.', 690),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B5.6.7.1', 'Demonstrate the use of Electronic Mail', 'B5.6.7.1.1', 'Identify the various e-mail service providers', 'Guide learners to explore on the various email service providers (email, outlook.com, icloud mail).', 700),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B5.6.7.1', 'Demonstrate the use of Electronic Mail', 'B5.6.7.1.2', 'Demonstrate the use of internet e-mail addresses', 'Guide learners to start an email address. Assist learners to use email address.', 710),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B5.6.7.1', 'Demonstrate the use of Electronic Mail', 'B5.6.7.1.3', 'Creating an email account', 'e.g. Yahoo mail or Gmail account. (Yahoo Mail or Gmail account.). Guide learners to create email account (i.e. the possible steps).', 720),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Electronic Email', 'B5.6.7.1', 'Demonstrate the use of Electronic Mail', 'B5.6.7.1.4', 'Illustrate viewing received messages and Create or Compose messages', 'Guide learners to write messages, format text, etc.', 730),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Internet of Things (IOT)', 'B5.6.8.1', 'Demonstrate the use of Internet of Things (IoT)', 'B5.6.8.1.1', 'Describe the purpose Internet of Things', 'Guide learners to discuss the IoT in groups.', 740),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Internet of Things (IOT)', 'B5.6.8.1', 'Demonstrate the use of Internet of Things (IoT)', 'B5.6.8.1.2', 'Give examples of Internet of Things with a consumer part and an industrial/business segment', 'Guide learners to give, explore and present in class examples of Internet of Things with a consumer part and an industrial/business segment.', 750),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Internet of Things (IOT)', 'B5.6.8.1', 'Demonstrate the use of Internet of Things (IoT)', 'B5.6.8.1.3', 'Identify components of Internet of Things. Guide learners to explore the components of the Internet of Things', 'e.g. Hardware, Data, Software and Connectivity.', 760),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Internet of Things (IOT)', 'B5.6.8.1', 'Demonstrate the use of Internet of Things (IoT)', 'B5.6.8.1.4', 'Identify the role of smart sensors in the Internet of Things. Guide learners to the explore the role of smart sensors in the Internet of Things', 'e.g. Sensing and data collection capability such as climatic change (e.g. Electronic Doors, RFID, CCTV camera, etc.), define at least five terms and acronyms of IoT. NB: This is to help the learner to fundamental knowledge of hardware such as robots and sensors).', 770),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Digital Literacy', 'B5.6.10.1', 'Demonstrated the application of Network Etiquette (Netiquette)', 'B5.6.10.1.1', 'Define digital footprint. Guide learners to explain digital footprint', null, 780),
('Basic 5', 'Computing', 'computing', 'Internet and Social Media', 'Digital Literacy', 'B5.6.10.1', 'Demonstrated the application of Network Etiquette (Netiquette)', 'B5.6.10.1.2', 'Illustrate how to keep some information from public when using the internet', 'Guide learner to avoid posting personal information', 790),
('Basic 5', 'Computing', 'computing', 'Health and Safety in Using ICT Tools', 'Health and Safety in Using ICT Tools', 'B5.7.1.1', 'Demonstrate the application of Health and safety measures, in using ICT tools', 'B5.7.1.1.1', 'Identify some major health hazards associated with the use of ICT tools’ use', 'Guide the learners to discuss wrist pain and sitting posture (neck, back and waist pain).', 800),
('Basic 5', 'Computing', 'computing', 'Health and Safety in Using ICT Tools', 'Health and Safety in Using ICT Tools', 'B5.7.1.1', 'Demonstrate the application of Health and safety measures, in using ICT tools', 'B5.7.1.1.2', 'Describe proper sitting posture', 'Guide learners in groups to discuss, identify and practise the proper sitting posture (i.e. siting at 90 degrees, wrist should be supported with a wrist pad, take short breaks etc.) when using the computer.', 810),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B5.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B5.1.1.1.1', 'Study some visual artworks created by Ghanaian and other African visual artists living in Africa and examine how the artworks reflect the history and culture of the people in Africa', 'Study the artworks e.g. sculpture, textiles, metal arts, paintings, cartoons, photography, ceramics created by Ghanaian and African visual artists e.g. El-Anatsui, Nnenna Okore, Cheri Samba, Goncalo Mabunda, Abdoulaye Konate, Peju Alatise, William J. Kentridge,  Justine Mahoney living in Africa by: a) gathering information through library studies, surfing the internet, visiting art studios, galleries, museums, exhibitions etc. watching short videos/documentaries or observing photographs of sample works of the collections of other Ghanaian and African artists. For example, ‘Warrior’ an installation art by El-Anatsui (2015), and ‘Story Maps of no Location’, painting by Julie Mehretu; b) talking about the works of the artists in relation to the history and culture of the people of Africa; c) identifying and discussing various items (symbols) found in the works being studied that reflect the history and culture of the people of Africa; d) writing a brief about their choice of artist using the following guidelines: - Name - Country of origin - Training - Type of artworks - Title of some works - Medium of expression.', 10),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B5.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B5.1.1.1.2', 'Explore to generate ideas by studying visual artworks created by selected Ghanaian and other African visual artists living in Africa that reflect the history and culture of the people of Africa', 'select an artwork of any of the artists studied in', 20),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B5.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B5.1.1.1.3', 'Study some artworks created by Ghanaian and other African visual artists studied that reflect the physical and social environments of some African communities', 'select the works of Ghanaian and other African visual artists; that reflect ideas from the physical and social environment of some African communities;; appreciate: talk about the works in-pairs and share their views during a plenary session (e.g. the type of artwork, theme/purpose, the idea from the physical and social environment that the artworks reflect, materials used, method of production);; compare the works in terms of type, function, materials, methods, etc.', 30),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B5.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B5.1.1.1.4', 'Generate own ideas for designing and creating own visual artworks that reflect the physical and social environments of some African communities', 'go out for field observation (out of class learning through environmental walk) to interact with the physical and social environment;; observe and record by sketching or taking photographs (still/moving) of a) structures (e.g. buildings, bridges) styles, shapes and forms). b) automobiles c) consumer services; packaging designs, etc.,; referencing the connection between the sale of slaves and liquor.', 40),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B5.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B5.1.1.1.5', 'Study the artworks of Ghanaian and other African visual artists that reflect topical  issues in Africa ', 'select works of Ghanaian and other African visual artists that reflect current topical issues of concern in Africa (e.g. climate change, water and air pollution, slums, inclusion, diversity, international relations, green cross and highway codes);; appreciate: through shower thoughts sessions discuss the works of the selected African artists with focus on the type of artwork, theme/purpose, materials, tools, method and style, etc.', 50),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Thinking and Exploring Ideas', 'B5.1.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions about the people based on their history and culture, the environment and topical local/national/global issues', 'B5.1.1.1.6', 'Brainstorm and come out with ideas for creating own visual works that will reflect topical issues in Africa', 'learn about current topical issues of concern in Africa using available OERs (e.g. libraries, internet, audio visuals, and other social media);; Create portfolios by using any of the following: a) downloading videos and other related documents from the internet b) jotting down simple notes and statements c) taking still and moving pictures d) making photocopies of relevant documents e) recording sound/voice messages, etc.; make presentations for class discussions and peer review for formative assessment (assessment as/of learning);; reflect on feedback from class discussions, peer reviews and formative assessment to generate concepts for designing and making own artworks that will reflect topical issues of concern in Africa.', 60),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making And Composing', 'B5.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B5.1.2.2.1', 'Experiment with available relevant visual arts media and methods to create own visual artworks that reflect the history and culture of the people of Africa', 'explore the local environment to select available materials and tools that are good for making artworks; study and experiment with available materials and tools to create simple artworks that reflect the history and culture of the people using appropriate methods and skills e.g. - clay, plasticine, papier mâché (paper pulp) etc. for modelling and casting; - straw, yarn, paper, etc. for weaving; - odds and ends for constructing and assembling; - brushes and paint for painting; - craft tools for perforating, shaping and punching; - folding and shaping paper to make origami and quilling; - spatula and scooping tools for modelling; - needle for sewing, etc.; discuss and share their experiences through jury and peer review;; use available materials in the environment to make artworks similar to the works studied;; discuss and compare their artworks to the artworks studied.', 70),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making And Composing', 'B5.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B5.1.2.2.2', 'Experiment with available relevant visual arts media and methods to create own visual artworks that reflect the physical and social environments of some African communities', 'explore the local environment to select available materials and tools that are good for making artworks; study and experiment with available materials and tools to create simple artworks that reflect the physical and social environments of some African communities using appropriate methods and skills: e.g. - clay, plasticine, papier mâché (paper pulp), etc. for modelling and casting; - straw, yarn, paper, etc. for weaving; - odds and ends for constructing and assembling; - brushes and paint for painting; - craft tools for perforating, shaping and punching; - folding and shaping paper to make origami and quilling; - spatula and scooping tools for modelling; - needle for sewing, etc.; discuss and share their experiences through jury and peer review;; use available materials in the environment to make artworks similar to the works studied;; discuss and compare their artworks to the artworks studied.', 80),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making And Composing', 'B5.1.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B5.1.2.2.3', 'Experiment with available relevant visual arts media and methods to create own visual artworks that reflect topical issues in Africa', 'explore the local environment to select available materials and tools that are good for making artworks;; study and experiment with available materials and tools to create simple artworks that reflect the emerging topical issues in Africa using appropriate methods and skills e.g. - clay, plasticine, papier mâché (paper pulp), etc. for modelling and casting; - straw, yarn, paper, etc. for weaving; - odds and ends for constructing and assembling; - brushes and paint for painting; - craft tools for perforating, shaping and punching; folding and shaping paper to make origami and quilling; - spatula and scooping tools for modelling; - needle for sewing, etc.; discuss and share their experiences through jury and peer review;; use available materials in the environment to make artworks similar to the works studied;; discuss and compare their artworks to the artworks studied.', 90),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making And Composing', 'B5.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production based on other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B5.1.2.3.1', 'Create own visual artworks based on own ideas, knowledge and understanding of artworks that reflect the history and culture of the people of Africa', 'demonstrate basic knowledge and skills in the use and application of the elements and principles of art and design, media, methods and techniques freely in creative and expressive ways to produce own 2-dimensional and 3-dimensional artworks based on own ideas and experiences;; make own comprehensive designs based on reflective memory of the history and culture of a selected group of Africans;; follow own design to produce personal artworks by selecting and using available but suitable and appropriate: a) materials available (e.g. clay for modelling and casting; paper for drawing and painting; colour for painting and spraying; wood and other solid materials for carving; glue for bonding; yarn for weaving) b) tools and equipment: e.g. - brush for painting; - scissors and cutting knives for cutting; - spray diffuser for spraying - chisel for carving - spatulas for modelling - craft tools for punching, perforating, etc. c) manual/mechanical production methods/techniques (e.g. painting, printing, weaving, knotting, trimming, doodling, modelling, casting, carving, construction, assemblage, folding, quilling); d) select and use suitable and appropriate manual/mechanical finishing and decorating techniques (e.g. firing, painting, burnishing, spraying).', 100),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making And Composing', 'B5.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production based on other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B5.1.2.3.2', 'Create own visual artworks based on own ideas, knowledge and understanding of artworks that reflect the physical and social environments of some communities in Africa', 'demonstrate basic knowledge and skills in the use and application of the elements and principles of art and design, media, methods and techniques freely in creative and expressive ways to produce own visual artworks based on own ideas and experiences;; make own comprehensive designs based on reflections on the physical and social environment of some communities in Africa;; follow own design to produce personal artwork by selecting and using available but suitable and appropriate: a) materials available (e.g. clay for modelling and casting; paper for drawing and painting; colour for painting and spraying; wood and other solid materials for carving; glue for bonding; yarn for weaving); b) tools and equipment e.g. - brush for painting; - scissors and cutting knives for cutting; - spray diffuser for spraying - chisel for carving - spatulas for modelling - craft tools for punching, perforating, etc.; c) manual/mechanical production methods/techniques (e.g. painting, printing, weaving, knotting, trimming, doodling, modelling, casting, carving, construction, assemblage, folding, quilling); d) select and use suitable and appropriate manual/mechanical finishing and decorating techniques (e.g. firing, painting, burnishing, spraying).', 110),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Planning, Making And Composing', 'B5.1.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production based on other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B5.1.2.3.3', 'Create own visual artworks based on own ideas, knowledge and understanding of of artworks that reflect topical issues in Africa', 'demonstrate basic knowledge and skills in the use and application of the elements and principles of art and design, media, methods and techniques freely in creative and expressive ways to produce own 2-dimensional and 3-dimensional artworks based on own ideas and experiences;; make own comprehensive designs based on reflective memory of current topical issues of much concern in Africa;; follow own design to produce personal artwork by selecting and using available but suitable and appropriate: a) materials available (e.g. clay for modelling and casting; paper for drawing and painting; colour for painting and spraying; wood and other solid materials for carving; glue for bonding; yarn for weaving); b) tools and equipment: e.g. - brush for painting; - scissors and cutting knives for cutting; - spray diffuser for spraying - chisel for carving - spatulas for modelling - craft tools for punching, perforating, etc. c) manual/mechanical production methods/techniques (e.g. painting, printing, weaving, knotting, trimming, doodling, modelling, casting, carving, construction, assemblage, folding, quilling); d) select and use suitable and appropriate manual/mechanical finishing and decorating techniques (e.g. firing, painting, burnishing, spraying). .', 120),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B5.1.3.4', 'Demonstrate understanding of how to plan a display/ presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B5.1.3.4.1', 'Plan an exhibition of own portfolio of visual artworks to educate and share creative experiences of artworks that reflect the history and culture of the people of Africa', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service);; discuss the need for displaying portfolio of own visual artworks;; develop a roadmap for the exhibition by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the exhibition (e.g. the African History and Culture).; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience such as parents, PTA/SMC members, stakeholders, colleague learners);; select works for the exhibition by considering (e.g. creativity and originality, finishing and decoration, relevance of the works to the theme, social and cultural importance);; decide on mode of display (e.g. hanging, draping, spreading);; plan the layout of the exhibition hall, prepare labels for the works (e.g. title, name of artist, date);; clean and prepare the hall and its environment and make it ready for the exhibition;; plan for post exhibition activities such as cleaning, appreciation, evaluation, reporting, etc.', 130),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B5.1.3.4', 'Demonstrate understanding of how to plan a display/ presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B5.1.3.4.2', 'Plan an exhibition of own portfolio of visual artworks to educate and share creative experiences of artworks that reflect the physical and social environments in some communities in Africa', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service);; discuss the need for displaying portfolio of own visual artworks;; develop a roadmap for the exhibition by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the exhibition (e.g. Our Environment);; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners);; select works for the exhibition by considering factors such as creativity and originality, finishing and decoration, relevance of the works to the theme, social and cultural importance;; decide on mode of display, e.g. hanging, draping, spreading;; plan the layout of the exhibition hall, prepare labels for the works (e.g. title, name of artist, date);; clean and prepare the hall and its environment and make it ready for the exhibition;; plan for post exhibition activities such as cleaning, appreciation, evaluation, reporting, etc.', 140),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B5.1.3.4', 'Demonstrate understanding of how to plan a display/ presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B5.1.3.4.3', 'Plan an exhibition of own portfolio of visual artworks to educate and share creative experiences of artworks that reflect the topical issues in Africa', 'watch a short video on an exhibition or visit an exhibition centre, preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service);; discuss the need for displaying portfolio of own visual artworks;; develop a roadmap for the exhibition by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the exhibition (e.g. the Future of Africa);; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, For example, parents, PTA/SMC members, stakeholders, colleague learners;; select works for the exhibition by considering (e.g. creativity and originality, finishing and decoration, relevance of the works to the theme, social and cultural importance);; decide on mode of display (e.g. by hanging, draping, spreading);; plan the layout of the exhibition hall, prepare labels for the works (e.g. title, name of artist, date);; clean and prepare the hall and its environment and make it ready for the exhibition.; plan for post exhibition activities such as cleaning, appreciation, evaluation, reporting, etc.', 150),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B5.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B5.1.3.5.1', 'Exhibit portfolio of own and others’ visual art artworks to share creative experiences of artworks that reflect the history and culture of the people of Africa', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that best tell the story of the history and culture of the people of Africa);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits;; label the works using manual penmanship (calligraphy) or ICT (computer) prints: name of artist, title of work, size of work, date of production;; assign tasks and responsibilities to themselves (individually or in groups) and ensure they are carried out successfully (e.g. leading visitors through the exhibition space, explaining the concepts/title of the artworks and the theme for the exhibition, writing of comments and signing of visitors’ books); NOTE; check/monitor visitors from improper practices (e.g. touching, lifting, handling and/or taking away some of the exhibits);; organise opening and closing ceremonies for the exhibition;; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the exhibition.', 160),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B5.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B5.1.3.5.2', 'Exhibit portfolio of own and others’ art artworks to share creative experiences of artworks that reflect the physical and social environments of some communities in Africa', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that best explains the physical and social environments of some communities in Africa).', 170),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Displaying and Sharing', 'B5.1.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B5.1.3.5.3', 'Exhibit portfolio of own and others’ art artworks to share creative experiences of artworks that reflect topical issues in Africa', 'decide on the types and number of artworks to exhibit and mount them based on the space available to suit the theme for the exhibition (e.g. artworks that best explains current topical issues of much concern in Africa);; display artworks by hanging, draping, placing, spreading, leaning, using plinths to raise or add height and depth to some exhibits;; label the works using manual penmanship (calligraphy) or ICT (computer) prints: name of artist, title of work, size of work, date of production;; assign tasks and responsibilities to themselves (individually or in groups) and ensure they are carried out successfully (e.g. leading visitors through the exhibition space, explaining the concepts/title of the artworks and the theme for the exhibition, writing of comments and signing of visitors’ books). Note; check/monitor visitors from improper practices (e.g. touching, lifting, handling and/or taking away some of the exhibits);; organise opening and closing ceremonies for the exhibition;; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the exhibition.', 180),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B5.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B5.1.4.6.1', 'Develop guidelines for appreciating and appraising own and others’ visual artworks that reflect the history and culture of the African people', 'discuss and accept a guide for appreciating and appraising own and/or others’ visual artworks based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks; ; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines; Description of the work: The elements in the work (dot, lines, shapes, forms, colour, texture, tone), materials used (e.g. paper, pencil, clay, wood), size of the work, number of objects/items in the work,; Subject matter: Meaning, message, topic, mood, feelings, history, religion, environment, global warming; Appraisal: What the work can be used for, likes, good things in the work, beauty, social and cultural value, correlation (connecting to other areas of learning); Experiences to share: The design process through thinking and composing, planning and making, displaying and sharing, etc.', 190),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B5.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B5.1.4.6.2', 'Develop guidelines for appreciating and appraising own and others’ visual artworks that reflect the physical and social environments of some communities in Africa', 'discuss and accept a guide for appreciating and appraising own and/or others’ visual artworks based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury.', 200),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B5.1.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B5.1.4.6.3', 'Develop guidelines for appreciating and appraising own and others’ visual artworks that reflect the topical issues in Africa', 'discuss and accept a guide for appreciating and appraising own and/or others’ visual artworks based on the guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising artworks;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested Guidelines; Description of the work: The elements in the work (e.g. dot, lines, shapes, forms, colour, texture, tone), materials used (e.g. paper, pencil, clay, wood), size of the work, number of objects/items in the work.; Subject matter: Meaning, message, topic, mood, feelings, history, religion, environment, global warming.; Appraisal: What the work can be used for, likes, good things in the work, beauty, social and cultural value, correlation (connecting to other areas of learning).; Experiences to share: The design process through thinking and composing, planning and making, displaying and sharing, etc.', 210),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B5.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B5.1.4.7.1', 'Analyse and appreciate own or others’ visual artworks and present reports as feedback on artworks that reflect the history and culture of the people of Africa', 'display (real/photographs/video) selected works (own or that of others) that reflect the history and culture of the people of Africa;; talk about the works dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another artwork;; record/document the activity and share using an accepted social media by the class/group e.g. Facebook, Twitter, Instagram, WhatsApp, etc.', 220),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B5.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B5.1.4.7.2', 'Analyse and appreciate own or others’ visual artworks and present reports as feedback on artworks that reflect the physical and social environments of some communities in Africa', 'display (real/photographs/video) selected works (own or that of others) that reflect the physical and social environments of some communities in Africa;; talk about the works dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another artwork;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 230),
('Basic 5', 'Creative Arts', 'creative arts', 'Visual Arts', 'Appreciating and Appraising', 'B5.1.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B5.1.4.7.3', 'Analyse and appreciate own or others’ visual artworks and present reports as feedback on artworks that reflect topical issues of much concern in Africa', 'display (real/photographs/video) selected works (own or that of others) that reflect current topical issues of much concern in Africa;; talk about the works dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another artwork;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 240),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B5.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B5.2.1.1.1', 'Explore and study some compositions and performances of Ghanaian and other African performing artists living in Africa and discuss how their works reflect the history and culture of the people of Africa', 'Study the compositions and performances of Ghanaian and other African performing  artists (e.g. Salif Keita, Angelique Kidjo, Chinua Achebe, Jack Mapanje, Dada Masilo,  Anton Robert Krueger, Hugh Masekela, Miriam Makeba, Asabea Cropper, John Okafor, OsitaIkema) by a) gathering information through OERs: library studies, internet surfing recorded videos, documentaries and other social media, as well as visits to recording studios, theatre, festival, cultural performances, concert parties, For example, ‘Things fall Apart’ by Chinua Achebe, and ‘Shaka the Zulu’ a South African television series was written by Joshua Sinclair and directed by William C. Faure; b) appreciate: discuss the compositions and performances of selected artists and find out how their works reflect the history and culture of Africans; c) write a brief about any of the artists of their choice using the following guidelines: - Name - Country of origin - Training - Type of compositions and performances - Title of some works - Style.', 250),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B5.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B5.2.1.1.2', 'Study how the compositions and performances of the Ghanaian and other African performing artists studied reflect the history and culture of the people of Africa and generate ideas for creating own artworks', 'select any composition or performance of a preferred artist studied in', 260),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B5.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B5.2.1.1.3', 'Study some compositions and performances of Ghanaian and other African  performing artists that reflect the physical and social environments of some African communities', 'select the works of Ghanaian and other African performing artists that reflect ideas from the physical and social environment of some African communities;; appreciate: talk about the art-forms in-pairs and share their views during a plenary session (e.g. the type of art-form, theme/purpose, the idea from the physical and social environment that the works reflect, style of composition, method of production and performance);; compare the works in terms of type, function, elements, tempo, rhythm, methods, etc.', 270),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B5.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B5.2.1.1.4', 'Generate own ideas for composing and performing own artworks that will reflect the physical and social environments of some African communities', 'use open educational resources (OERs) such as libraries, internet, audio-visuals to study the physical and social environment of other African communities;; observe the movement patterns, arrangements and activities of the physical and social environment: a) structures (e.g. buildings, bridges), styles, shapes and forms); b) automobiles; c) commercials and jingles', 280),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B5.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B5.2.1.1.5', ' Study the compositions and performances of Ghanaian and other African performing artists that reflect topical issues in Africa', 'select compositions and performances of other Ghanaian and African performing artists that reflect current topical issues of much concern in Africa (e.g. climate change, water and air pollution, slums, inclusion, diversity, international relations);; appreciate: through shower thoughts session discuss the compositions and performances of the selected African artists with focus on the type of art-forms, theme/purpose, elements, dynamics, tempo, instruments, style, etc.', 290),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Thinking and Exploring Ideas', 'B5.2.1.1', 'Demonstrate understanding of how to generate own ideas for artistic expressions on the people based on their history and culture, the environment and topical local/national/global issues', 'B5.2.1.1.6', 'Brainstorm to generate ideas for creating own compositions and performances that reflect topical issues in Africa', 'learn about current topical issues of much concern in Africa using available OERs, e.g. libraries, internet, audio-visuals, and other social media;; create portfolios by using any of the following: a) downloading videos and other related documents from the internet; b) jotting down simple notes and statements; c) recording sound/voice messages, etc.;; make presentations for class discussions and peer review for formative assessment (assessment as/of learning);; reflect on feedback from class discussions, peer reviews and formative assessment to generate concepts for designing and making own artworks that will reflect current topical issues of much concern in Africa.', 300),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B5.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B5.2.2.2.1', 'Experiment with available relevant performing arts media and techniques to create own performing artworks that reflect the history and culture of the people of Africa', 'explore the local environment to select available instruments, equipment, sounds, melody, rhythms, movement patterns that are good for composing/arranging and performing music, dance, drama, poems, appellations, etc.;; experiment with the available instruments, equipment, sounds, movement patterns, melody, etc. to perform some of the compositions of the Ghanaian artists studied that reflect the history and culture of the people of Africa;; discuss and share their experiences through peer review.', 310),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B5.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B5.2.2.2.2', 'Experiment with available relevant performing arts media and techniques to create own performing artworks that reflect the physical and social environments of some communities in Africa', 'explore the local environment to select available instruments, equipment, sounds, melody, rhythms, movement patterns that are good for composing/arranging and performing music, dance, drama, poems, appellations, etc.;; experiment with the available instruments, equipment, sounds, movement patterns, melody etc. to perform some of the compositions of the Ghanaian artists studied that reflect the physical and social environment of some communities in Africa;; discuss and share their experiences through peer review.', 320),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B5.2.2.2', 'Demonstrate understanding of how to organise own ideas through experimenting with available media and techniques for creating/composing artworks based on the history, culture, environment and topical local/national/global issues of other communities', 'B5.2.2.2.3', 'Experiment with available relevant performing arts media and techniques to create own performing artworks that reflect topical issues in Africa', 'explore the local environment to select available instruments, equipment, sounds, melody, rhythms, movement patterns that are good for composing/arranging and performing music, dance, drama, poems, appellations, etc.;; experiment with the available instruments, equipment, sounds, movement patterns, melody etc. to perform some of the compositions of the Ghanaian artists studied that reflect topical issues of much concern in Africa;; discuss and share their experiences through peer review.', 330),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B5.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B5.2.2.3.1', 'Create own performing artworks based on own ideas, knowledge and understanding of artworks that reflect the history and culture of the people of Africa', 'demonstrate basic knowledge and skills in the use and application of the elements and principles of performing arts, instruments, equipment and techniques freely in creative and expressive ways to produce own music, dance, drama, poetry etc. based on own ideas and experiences;; make own compositions based on reflective memory of the history and culture of a selected group of Africans;; produce music, dance, drama etc. based on own skills, talents and experience by selecting and using available but suitable and appropriate: a) instruments, elements, resources, equipment available (e.g. xylophone, drums, flutes, bells, shakers, rasp, finger piano, rattles, clappers, castanets, horn, whistles, harp, costumes, props); b) manual/mechanical/electronic production methods/techniques (e.g. voice, gestures, movements, language, improvisation, imitation, adaptation, guided writing skills to communicate feelings, melodic, rhythmic, harmonic and dynamic elements, dramatization); c) props, scenery, and costumes for different styles and performances which support and enhance the intent of a production.', 340),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B5.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B5.2.2.3.2', 'Create own performing artworks based on own ideas, knowledge and understanding of artworks that reflect the physical and social environments of some communities in Africa', 'demonstrate basic knowledge and skills in the use and application of the elements and principles of performing arts, instruments, equipment and techniques freely in creative and expressive ways to produce own music, dance, drama, poetry, etc. based on own ideas and experiences;; make own compositions based on reflective memory of the physical and social environments of some communities in Africa', 350),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Planning, Making and Composing', 'B5.2.2.3', 'Demonstrate understanding of how to create expressive artworks based on own ideas by applying knowledge of media and methods of production to reflect other cultures in Africa, the visual artists, their culture, the environment and emerging topical issues', 'B5.2.2.3.3', 'Create own performing artworks based on own ideas, knowledge and understanding of artworks that reflect topical issues in Africa', 'demonstrate basic knowledge and skills in the use and application of the elements and principles of performing arts, instruments, equipment and techniques freely in creative and expressive ways to produce own music, dance, drama, poetry etc. based on own ideas and experiences;; make own compositions based on reflective memory of current topical physical and social issues in Africa;; produce music, dance, drama etc. based on own skills, talents and experience by selecting and using available but suitable and appropriate: a) instruments, elements, resources, equipment available (e.g. xylophone, drums, flutes, bells, shakers, rasp, finger piano, rattles, clappers, castanets, horn, whistles, harp, costumes, props); b) manual/mechanical/electronic production methods/techniques (e.g. voice, gestures, movements, language, improvisation, imitation, adaptation, guided writing skills to communicate feelings, melodic, rhythmic, harmonic and dynamic elements, dramatization); c) props, scenery, and costumes for different styles and performances which support and enhance the intent of a production.', 360),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B5.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B5.2.3.4.1', 'Plan a display of own portfolio of performing artworks to educate and share creative experiences of artworks that reflect the history and culture of the people of Africa', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect the history and culture of the people of Africa;; discuss the need for performing compositions of own music, dance, drama, poetry, etc.;; develop a roadmap for the performances by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the performance (e.g. The Pride of African Culture);; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E- mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners);; select compositions by considering (e.g. creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance);; decide on mode and arrangement of performances, e.g. monologue/solo/group, costumes, props, etc.;; getting ready: plan the sequence of events, stage/site plan identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners), characters, directors, stage managers, audience, health and security personnel);; clean and prepare the venue and its environment and make it ready for the performance;; plan for post-performance activities such as cleaning, appreciation, evaluation, reporting, etc.', 370),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B5.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B5.2.3.4.2', 'Plan a display of own portfolio of performing artworks to educate and share creative experiences of artworks that reflect the physical and social environments of some communities of Africa', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect the physical and social environment of Africa;; discuss the need for performing compositions of own music, dance, drama, poetry etc.;; develop a roadmap for the performances by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the performance (e.g. Our Continent Africa);; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E- mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners);; select compositions by considering factors such as creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance;; decide on mode and arrangement of performances, e.g. monologue/solo/group, costumes, props, etc.;; getting ready: plan the sequence of events, stage/site plan identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners), characters, directors, stage managers, audience, health and security personnel);; clean and prepare the venue and its environment and make it ready for the performance.; plan for post-performance activities such as cleaning, appreciation, evaluation, reporting, etc.', 380),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B5.2.3.4', 'Demonstrate understanding of how to plan a display/presentation of a portfolio of own artworks by identifying, and preparing a venue, selecting and grouping of artworks and inviting target audience for the planned display/performance', 'B5.2.3.4.3', 'Plan a display of own portfolio of performing artworks to educate and share creative experiences of artworks that reflect the topical issues in Africa', 'watch a short video or live performances (preferably during the circuit, district or regional cultural festival of the cultural education unit of the Ghana Education Service) that reflect the physical and social environments of Africa;; discuss the need for performing compositions of own music, dance, drama, poetry etc.;; develop a roadmap for the performances by: - fixing a date - selecting a venue - inviting an audience; brainstorm to agree on a theme for the performance (e.g. The Future of Africa);; send manual and/or electronic invitations (e.g. letters, postcards, WhatsApp, E-mail, Twitter, Instagram, Facebook, announcements, posters, jingles) to target audience, for example parents, PTA/SMC members, stakeholders, colleague learners);; select compositions by considering (e.g. creativity and originality, lyrics, movement patterns, dynamics and relevance of the message to the theme, social and cultural importance);; decide on mode and arrangement of performances (e.g. monologue/solo/group, costumes, props, etc.);; getting ready: plan the sequence of events, stage/site plan identifying the positions of all facilities (e.g. PA system, lightings, performance zone, entry, exit, changing and makeup rooms/corners), characters, directors, stage managers, audience, health and security personnel);; clean and prepare the venue and its environment and make it ready for the performance;; plan for post-performance activities such as cleaning, appreciation, evaluation, reporting, etc.', 390),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B5.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B5.2.3.5.1', 'Stage a display of own portfolio of performing artworks to share creative experiences of compositions that reflect the history and culture of the people of Africa', 'decide on the types and number of compositions to be performed during the event to reflect the history and culture of the people of Africa based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show (e.g. explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions);; arrange the sequence of performances to best tell the story of the event from the beginning to the end;; follow the programme of the day: opening, performances and closing. NOTE; prepare template for appreciating, appraising, evaluating and reporting, etc.; clean the hall after the performance.', 400),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B5.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B5.2.3.5.2', 'Stage a display of own portfolio of performing artworks to share creative experiences of compositions that reflect the physical and social environments of some communities in Africa', 'decide on the types and number of compositions to be performed during the event to reflect the physical and social environments of some communities in Africa based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully (e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show (e.g. explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions)', 410),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Displaying and Sharing', 'B5.2.3.5', 'Demonstrate understanding of how to display/present a portfolio of art works that share own knowledge, concepts, ideas and experiences with audience through display/presentation; and using senses/manual/digital applications where necessary, to record for reporting on the events', 'B5.2.3.5.3', 'Stage a display of own portfolio of performing artworks to share own creative experiences of compositions that reflect the topical issues in Africa', 'decide on the types and number of compositions to be performed during the event to reflect current topical issues of much concern in Africa based on the selected theme, time available and the expected audience;; assign individual and group tasks and responsibilities and ensure they are carried out successfully (e.g. master of ceremony, ushering and introduction of special guests and other dignitaries to the show by explaining the concepts/title of the compositions, performances and the theme for the event, recording of comments and suggestions);; arrange the sequence of performances to best tell the story of the event from the beginning to the end;; follow the programme of the day: opening, performances and closing. NOTE; prepare template for appreciating, appraising, evaluating and reporting, etc.;; clean the hall after the performance.', 420),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B5.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B5.2.4.6.1', 'Develop guidelines for appreciating and appraising own and others’ performing artworks that reflect the history and culture of the people of Africa', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others’ compositions and performances on the guide guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and  drama;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested guidelines; Music: theme, voice production and diction, harmony and blending of parts, interpretation, the elements and knowledge of music.; Dance: theme, entrance/exit, movement variation, gestures, creativity, makeup, movement in relation to singing and drumming, costume, props, energy, stage use, stage setting and dynamics; Drama: characterisation, makeup, gestures, voice projection, diction, use of space, aesthetics, creativity.', 430),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B5.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B5.2.4.6.2', 'Develop guidelines for appreciating and appraising own and others’ performing artworks that reflect the physical and social environment of some communities in Africa', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others’ compositions and performances on the guide guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and drama;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury.', 440),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B5.2.4.6', 'Demonstrate understanding of how to analyse, appreciate, appraise/critique and present report on own works and that of others based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values), the recordings and reports', 'B5.2.4.6.3', 'Develop guidelines for appreciating and appraising own and others’ performing artworks that reflect topical issues in Africa', 'discuss and accept a guide for analysing and appreciating/appraising own and/or others’ compositions and performances on the guide guidelines suggested below;; identify the correct vocabulary to use for appreciating and appraising music, dance and drama;; agree on what to use the appraisal report for and how to share it;; agree on the approach/method (manual/digital) to use in recording/documenting the appraisal process;; fix a day/date for the appreciation/appraisal/jury. Suggested guidelines; Music: theme, voice production and diction, harmony and blending of parts, interpretation, the elements and knowledge of music.; Dance: theme, entrance/exit, movement variation, gestures, creativity, makeup, movement in relation to singing and drumming, costume, props, energy, stage use, stage setting and dynamics.; Drama: characterisation, makeup, gestures, voice projection, diction, use of space, aesthetics, creativity.', 450),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B5.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B5.2.4.7.1', 'Analyse and appreciate own or others’ performing artworks and present reports as feedback on compositions that reflect the history and culture of the people of Africa', 'display (photographs/video) of selected performances (own or that of others) that reflect the history and culture of the people of Africa;; talk about the performances dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another composition and performance;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 460),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B5.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B5.2.4.7.2', 'Analyse and appreciate own or others’ performing artworks and present reports as feedback on compositions that reflect the physical and social environments of some communities in Africa', 'display (photographs/video) of selected performances (own or that of others) that reflect the physical and social environments of some communities in Africa;; talk about the performances dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another composition and performance;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 470),
('Basic 5', 'Creative Arts', 'creative arts', 'Performing Arts', 'Appreciating and Appraising', 'B5.2.4.7', 'Demonstrate understanding of how to make informed decisions on displays, presentations, performances, recordings and/or reports based on established guide for judging artworks (the theme, subject matter, media, techniques, elements and principles of design, social, aesthetic, cultural and functional values) for correlation, correction and future modifications', 'B5.2.4.7.3', 'Analyse and appreciate/appraise own or others’ performing artworks and present reports as feedback on compositions that reflect topical issues in Africa', 'display (photographs/video) of selected performances (own or that of others) that reflect current topical issues of much concern in Africa;; talk about the performances dispassionately using agreed guidelines;; use the outcome of the appreciation/appraisal to modify the product or to produce similar or another composition and performance;; record/document the activity and share using an accepted social media by the class/group (e.g. Facebook, Twitter, Instagram, WhatsApp).', 480);
