-- NaCCA curriculum for Basic 5 (part 1 of 3): 129 indicators (Computing, Creative Arts).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 5.
delete from public.curriculum_items
 where lower(class_name) = 'basic 5' and subject_key in ('computing', 'creative arts');

